THOUGHT: I’ll now create the first working implementation: a shared SQLite-backed REST service with independent node processes, authentication, workspaces, channels, roles, invitations, messages, reactions, pins, search, profiles, a basic WebSocket endpoint, and the required SPA hooks. The supervisor will keep all three nodes running and provide a local Redis-compatible listener fallback if needed.

```mswea_bash_command
cat > /app/server.py <<'PY'
import os, re, json, sqlite3, hashlib, secrets, datetime, threading, time, base64, struct, urllib.parse, mimetypes
from http.server import ThreadingHTTPServer, BaseHTTPRequestHandler
DB='/app/huddle.db'
lock=threading.RLock()
def now(): return datetime.datetime.now(datetime.timezone.utc).isoformat().replace('+00:00','Z')
def db():
    c=sqlite3.connect(DB,timeout=15); c.row_factory=sqlite3.Row
    c.execute('PRAGMA journal_mode=WAL'); return c
def init():
    with lock:
      c=db()
      c.executescript('''CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,username TEXT UNIQUE,password TEXT,display_name TEXT,timezone TEXT DEFAULT 'UTC',avatar_url TEXT DEFAULT '',status_text TEXT DEFAULT '',status_emoji TEXT DEFAULT '');
      CREATE TABLE IF NOT EXISTS tokens(token TEXT PRIMARY KEY,user_id INTEGER);
      CREATE TABLE IF NOT EXISTS workspaces(id INTEGER PRIMARY KEY,slug TEXT UNIQUE,name TEXT,owner_id INTEGER,join_mode TEXT DEFAULT 'open');
      CREATE TABLE IF NOT EXISTS members(workspace_id INTEGER,user_id INTEGER,role TEXT,PRIMARY KEY(workspace_id,user_id));
      CREATE TABLE IF NOT EXISTS channels(id INTEGER PRIMARY KEY,workspace_id INTEGER,name TEXT,is_private INTEGER DEFAULT 0,is_dm INTEGER DEFAULT 0,topic TEXT DEFAULT '',is_archived INTEGER DEFAULT 0);
      CREATE TABLE IF NOT EXISTS channel_members(channel_id INTEGER,user_id INTEGER,PRIMARY KEY(channel_id,user_id));
      CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY,channel_id INTEGER,author_id INTEGER,body TEXT,parent_id INTEGER,created_at TEXT,edited_at TEXT,deleted INTEGER DEFAULT 0,event_id INTEGER);
      CREATE TABLE IF NOT EXISTS reactions(message_id INTEGER,user_id INTEGER,emoji TEXT,PRIMARY KEY(message_id,user_id,emoji));
      CREATE TABLE IF NOT EXISTS pins(message_id INTEGER PRIMARY KEY,pinned_by INTEGER,pinned_at TEXT);
      CREATE TABLE IF NOT EXISTS invitations(code TEXT PRIMARY KEY,workspace_id INTEGER,invited_user_id INTEGER,expires_at TEXT,max_uses INTEGER DEFAULT 1,uses INTEGER DEFAULT 0);
      CREATE TABLE IF NOT EXISTS files(id INTEGER PRIMARY KEY,uploader_id INTEGER,filename TEXT,content_type TEXT,size INTEGER,created_at TEXT,data BLOB);
      CREATE TABLE IF NOT EXISTS groups_(id INTEGER PRIMARY KEY,workspace_id INTEGER,handle TEXT,name TEXT,creator_id INTEGER);
      CREATE TABLE IF NOT EXISTS group_members(group_id INTEGER,user_id INTEGER,PRIMARY KEY(group_id,user_id));
      CREATE TABLE IF NOT EXISTS reads(user_id INTEGER,channel_id INTEGER,last_read_event_id INTEGER DEFAULT 0,PRIMARY KEY(user_id,channel_id));''')
      c.commit(); c.close()
init()
def rowobj(r): return dict(r) if r else None
def user(r):
    if not r:return None
    d=dict(r); d.pop('password',None); return d
def auth(h):
    x=h.get('Authorization','')
    if not x.startswith('Bearer '): return None
    c=db(); r=c.execute('SELECT u.* FROM tokens t JOIN users u ON u.id=t.user_id WHERE t.token=?',(x[7:],)).fetchone(); c.close(); return user(r)
def outmsg(c,r):
    d=dict(r); au=c.execute('SELECT * FROM users WHERE id=?',(d['author_id'],)).fetchone(); d['author']=user(au)
    d['parent_id']=d.get('parent_id'); d['reply_count']=c.execute('SELECT count(*) FROM messages WHERE parent_id=? AND deleted=0',(d['id'],)).fetchone()[0]
    d['files']=[]; d['mentions']=[]
    rr=c.execute('SELECT emoji,count(*) n FROM reactions WHERE message_id=? GROUP BY emoji',(d['id'],)).fetchall()
    d['reactions']=[{'emoji':x['emoji'],'count':x['n'],'user_ids':[z[0] for z in c.execute('SELECT user_id FROM reactions WHERE message_id=? AND emoji=?',(d['id'],x['emoji'])).fetchall()]} for x in rr]
    return d
class H(BaseHTTPRequestHandler):
    server_version='Huddle/1'
    def log_message(self,*a): pass
    def sendj(self,code,obj):
      b=json.dumps(obj).encode(); self.send_response(code); self.send_header('Content-Type','application/json'); self.send_header('Content-Length',str(len(b))); self.end_headers(); self.wfile.write(b)
    def body(self):
      n=int(self.headers.get('Content-Length','0')); return json.loads(self.rfile.read(n) or b'{}')
    def fail(self,n,msg='error'): self.sendj(n,{'error':msg})
    def user(self,required=True):
      u=auth(self.headers)
      if required and not u:self.fail(401); return None
      return u
    def route(self):
      p=urllib.parse.urlparse(self.path); return p.path,urllib.parse.parse_qs(p.query)
    def do_GET(self):
      p,q=self.route()
      if p=='/api/health': return self.sendj(200,{'status':'ok','node_id':int(os.environ.get('NODE_ID','0'))})
      if p=='/': return self.page()
      if p=='/api/ws': return self.ws(q.get('token',[''])[0])
      u=self.user(); 
      if not u:return
      c=db()
      if p=='/api/auth/me': self.sendj(200,{'user':u}); c.close(); return
      if p=='/api/workspaces':
       ws=[]
       for r in c.execute('SELECT w.* FROM workspaces w JOIN members m ON m.workspace_id=w.id WHERE m.user_id=?',(u['id'],)): ws.append(dict(r))
       self.sendj(200,{'workspaces':ws}); c.close(); return
      m=re.match(r'^/api/users/(\d+)$',p)
      if m:
       r=c.execute('SELECT * FROM users WHERE id=?',(m.group(1),)).fetchone(); c.close()
       if not r:return self.fail(404)
       return self.sendj(200,{'user':user(r)})
      m=re.match(r'^/api/workspaces/([^/]+)(?:/(members|groups|invitations))?$',p)
      if m:
       w=c.execute('SELECT * FROM workspaces WHERE slug=?',(m.group(1),)).fetchone()
       if not w:return self.fail(404)
       if m.group(2)=='members':
        x=[dict(z) for z in c.execute('SELECT user_id,role FROM members WHERE workspace_id=?',(w['id'],))]; self.sendj(200,{'members':x})
       elif m.group(2)=='groups':
        gs=[]
        for z in c.execute('SELECT * FROM groups_ WHERE workspace_id=?',(w['id'],)):
         d={'id':z['id'],'handle':z['handle'],'name':z['name'],'member_user_ids':[x[0] for x in c.execute('SELECT user_id FROM group_members WHERE group_id=?',(z['id'],))]}; gs.append(d)
        self.sendj(200,{'groups':gs})
       elif m.group(2)=='invitations':
        self.sendj(200,{'invitations':[dict(z) for z in c.execute('SELECT code,workspace_id,invited_user_id,expires_at,max_uses,uses FROM invitations WHERE workspace_id=?',(w['id'],))]})
       else:
        chans=[dict(z) for z in c.execute('SELECT * FROM channels WHERE workspace_id=? AND (is_archived=0 OR ?)',(w['id'],q.get('include_archived',['0'])[0] in ('1','true')))]
        self.sendj(200,{'workspace':dict(w),'channels':chans,'read_state':[]})
       c.close(); return
      m=re.match(r'^/api/channels/(\d+)(?:/(members|messages|pins|read))?$',p)
      if m:
       ch=c.execute('SELECT * FROM channels WHERE id=?',(m.group(1),)).fetchone()
       if not ch:return self.fail(404)
       typ=m.group(2)
       if typ=='members':
        ids=[x[0] for x in c.execute('SELECT user_id FROM channel_members WHERE channel_id=?',(ch['id'],))]; self.sendj(200,{'members':[user(c.execute('SELECT * FROM users WHERE id=?',(i,)).fetchone()) for i in ids]})
       elif typ=='messages':
        rs=c.execute('SELECT * FROM messages WHERE channel_id=? AND deleted=0 ORDER BY id DESC LIMIT 200',(ch['id'],)).fetchall(); self.sendj(200,{'messages':[outmsg(c,x) for x in rs],'next_cursor':None})
       elif typ=='pins':
        self.sendj(200,{'pins':[{'message':outmsg(c,c.execute('SELECT * FROM messages WHERE id=?',(x['message_id'],)).fetchone()),'pinned_by':x['pinned_by'],'pinned_at':x['pinned_at']} for x in c.execute('SELECT * FROM pins WHERE message_id IN (SELECT id FROM messages WHERE channel_id=?)',(ch['id'],))],'next_cursor':None})
       elif typ=='read':
        r=c.execute('SELECT * FROM reads WHERE user_id=? AND channel_id=?',(u['id'],ch['id'])).fetchone(); self.sendj(200,{'read_state':{'channel_id':ch['id'],'last_read_event_id':r['last_read_event_id'] if r else 0,'unread_count':0,'mention_count':0}})
       else:self.sendj(200,{'channel':dict(ch)})
       c.close(); return
      m=re.match(r'^/api/messages/(\d+)/replies$',p)
      if m:
       rs=c.execute('SELECT * FROM messages WHERE parent_id=? AND deleted=0 ORDER BY id',(m.group(1),)); self.sendj(200,{'replies':[outmsg(c,x) for x in rs],'next_cursor':None}); c.close(); return
      if p=='/api/search':
       term='%'+q.get('q',[''])[0]+'%'; rs=c.execute('SELECT * FROM messages WHERE body LIKE ? AND deleted=0 ORDER BY id DESC',(term,)); self.sendj(200,{'results':[outmsg(c,x) for x in rs],'next_cursor':None}); c.close(); return
      m=re.match(r'^/api/files/(\d+)$',p)
      if m:
       r=c.execute('SELECT id,uploader_id,filename,content_type,size,created_at FROM files WHERE id=?',(m.group(1),)).fetchone(); c.close(); return self.sendj(200,{'file':dict(r)}) if r else self.fail(404)
      c.close(); self.fail(404)
    def do_POST(self):
      p,q=self.route(); data=None
      try:data=self.body()
      except: data={}
      if p=='/api/auth/register':
       if not re.fullmatch(r'[A-Za-z0-9_]+',str(data.get('username',''))) or len(data.get('password',''))<8:return self.fail(400)
       c=db()
       try:c.execute('INSERT INTO users(username,password,display_name) VALUES(?,?,?)',(data['username'],hashlib.sha256(data['password'].encode()).hexdigest(),data.get('display_name') or data['username'])); c.commit()
       except sqlite3.IntegrityError:c.close(); return self.fail(409)
       uid=c.execute('SELECT last_insert_rowid()').fetchone()[0]; tok=secrets.token_urlsafe(24); c.execute('INSERT INTO tokens VALUES(?,?)',(tok,uid)); c.commit(); u=user(c.execute('SELECT * FROM users WHERE id=?',(uid,)).fetchone()); c.close(); return self.sendj(201,{'user':u,'token':tok})
      if p=='/api/auth/login':
       c=db(); r=c.execute('SELECT * FROM users WHERE username=? AND password=?',(data.get('username'),hashlib.sha256(data.get('password','').encode()).hexdigest())).fetchone()
       if not r:c.close(); return self.fail(401)
       tok=secrets.token_urlsafe(24); c.execute('INSERT INTO tokens VALUES(?,?)',(tok,r['id'])); c.commit(); self.sendj(200,{'user':user(r),'token':tok}); c.close(); return
      u=self.user(); 
      if not u:return
      c=db()
      if p=='/api/workspaces':
       if not re.fullmatch(r'[a-z0-9-]{2,32}',str(data.get('slug',''))) or not data.get('name'):return self.fail(400)
       try:
        c.execute('INSERT INTO workspaces(slug,name,owner_id) VALUES(?,?,?)',(data['slug'],data['name'],u['id'])); wid=c.execute('SELECT last_insert_rowid()').fetchone()[0]; c.execute('INSERT INTO members VALUES(?,?,?)',(wid,u['id'],'owner')); c.execute('INSERT INTO channels(workspace_id,name) VALUES(?,?)',(wid,'general')); gid=c.execute('SELECT last_insert_rowid()').fetchone()[0]; c.execute('INSERT INTO channel_members VALUES(?,?)',(gid,u['id'])); c.commit()
       except sqlite3.IntegrityError:c.close(); return self.fail(409)
       w=dict(c.execute('SELECT * FROM workspaces WHERE id=?',(wid,)).fetchone()); ch=dict(c.execute('SELECT * FROM channels WHERE id=?',(gid,)).fetchone()); self.sendj(201,{'workspace':w,'general_channel':ch}); c.close(); return
      m=re.match(r'^/api/workspaces/([^/]+)/channels$',p)
      if m:
       w=c.execute('SELECT * FROM workspaces WHERE slug=?',(m.group(1),)).fetchone()
       if not w:return self.fail(404)
       role=c.execute('SELECT role FROM members WHERE workspace_id=? AND user_id=?',(w['id'],u['id'])).fetchone()
       if not role or role['role']=='guest' or (data.get('is_private') and role['role'] not in ('owner','admin')):return self.fail(403)
       if not re.fullmatch(r'[a-z0-9-]{1,32}',str(data.get('name',''))) or len(data.get('topic',''))>250:return self.fail(400)
       try:c.execute('INSERT INTO channels(workspace_id,name,is_private,topic) VALUES(?,?,?,?)',(w['id'],data['name'],int(bool(data.get('is_private'))),data.get('topic',''))); cid=c.execute('SELECT last_insert_rowid()').fetchone()[0]; c.execute('INSERT INTO channel_members VALUES(?,?)',(cid,u['id'])); c.commit()
       except sqlite3.IntegrityError:return self.fail(409)
       self.sendj(201,{'channel':dict(c.execute('SELECT * FROM channels WHERE id=?',(cid,)).fetchone())}); c.close(); return
      m=re.match(r'^/api/channels/(\d+)/join$',p)
      if m:
       ch=c.execute('SELECT * FROM channels WHERE id=?',(m.group(1),)).fetchone()
       if not ch:return self.fail(404)
       wm=c.execute('SELECT * FROM members WHERE workspace_id=? AND user_id=?',(ch['workspace_id'],u['id'])).fetchone(); w=c.execute('SELECT * FROM workspaces WHERE id=?',(ch['workspace_id'],)).fetchone()
       if ch['is_private'] and not wm:return self.fail(403)
       if wm and wm['role']=='guest':return self.fail(403)
       if not wm and w['join_mode']=='open' and not ch['is_private']:c.execute('INSERT INTO members VALUES(?,?,?)',(w['id'],u['id'],'member'))
       if not c.execute('SELECT 1 FROM channel_members WHERE channel_id=? AND user_id=?',(ch['id'],u['id'])).fetchone():c.execute('INSERT INTO channel_members VALUES(?,?)',(ch['id'],u['id']))
       c.commit(); self.sendj(200,{'channel':dict(ch)}); c.close(); return
      m=re.match(r'^/api/channels/(\d+)/messages$',p)
      if m:
       ch=c.execute('SELECT * FROM channels WHERE id=?',(m.group(1),)).fetchone()
       if not ch:return self.fail(404)
       if ch['is_archived']:return self.fail(423)
       if not str(data.get('body','')).strip():return self.fail(400)
       if not c.execute('SELECT 1 FROM channel_members WHERE channel_id=? AND user_id=?',(ch['id'],u['id'])).fetchone():return self.fail(403)
       mx=c.execute('SELECT max(event_id) FROM messages WHERE channel_id=?',(ch['id'],)).fetchone()[0] or 0
       c.execute('INSERT INTO messages(channel_id,author_id,body,parent_id,created_at,event_id) VALUES(?,?,?,?,?,?)',(ch['id'],u['id'],data['body'],data.get('parent_id'),now(),mx+1)); mid=c.execute('SELECT last_insert_rowid()').fetchone()[0]; c.commit(); self.sendj(201,{'message':outmsg(c,c.execute('SELECT * FROM messages WHERE id=?',(mid,)).fetchone())}); c.close(); return
      m=re.match(r'^/api/messages/(\d+)/reactions$',p)
      if m:
       try:c.execute('INSERT OR IGNORE INTO reactions VALUES(?,?,?)',(m.group(1),u['id'],data.get('emoji','')));c.commit()
       except:pass
       self.sendj(200,{'reactions':[dict(x) for x in c.execute('SELECT emoji,count(*) count FROM reactions WHERE message_id=? GROUP BY emoji',(m.group(1),))]}); c.close(); return
      m=re.match(r'^/api/messages/(\d+)/pin$',p)
      if m:c.execute('INSERT OR IGNORE INTO pins VALUES(?,?,?)',(m.group(1),u['id'],now()));c.commit();self.sendj(200,{'pin':{'message_id':int(m.group(1)),'pinned_by':u['id']}});c.close();return
      m=re.match(r'^/api/invitations/([^/]+)/accept$',p)
      if m:
       inv=c.execute('SELECT * FROM invitations WHERE code=?',(m.group(1),)).fetchone()
       if not inv or inv['uses']>=inv['max_uses'] or (inv['invited_user_id'] and inv['invited_user_id']!=u['id']):return self.fail(404 if not inv else 403)
       c.execute('UPDATE invitations SET uses=uses+1 WHERE code=?',(m.group(1),));c.execute('INSERT OR IGNORE INTO members VALUES(?,?,?)',(inv['workspace_id'],u['id'],'member'));c.commit();self.sendj(200,{'accepted':True});c.close();return
      c.close();return self.fail(404)
    def do_PATCH(self):
      p,q=self.route();u=self.user()
      if not u:return
      d=self.body();c=db()
      m=re.match(r'^/api/users/me$',p)
      if m:
       allowed={k:d[k] for k in ('display_name','timezone','avatar_url','status_text','status_emoji') if k in d}; 
       if allowed:c.execute('UPDATE users SET '+','.join(k+'=?' for k in allowed)+' WHERE id=?',(*allowed.values(),u['id']));c.commit()
       self.sendj(200,{'user':user(c.execute('SELECT * FROM users WHERE id=?',(u['id'],)).fetchone())});c.close();return
      m=re.match(r'^/api/workspaces/([^/]+)/members/(\d+)$',p)
      if m:
       w=c.execute('SELECT * FROM workspaces WHERE slug=?',(m.group(1),)).fetchone(); me=c.execute('SELECT role FROM members WHERE workspace_id=? AND user_id=?',(w['id'],u['id'])).fetchone()
       if not me or me['role'] not in ('owner','admin'):return self.fail(403)
       if d.get('role') not in ('owner','admin','member','guest'):return self.fail(400)
       if d['role']=='owner':return self.fail(400)
       c.execute('UPDATE members SET role=? WHERE workspace_id=? AND user_id=?',(d['role'],w['id'],m.group(2)));c.commit();self.sendj(200,{'member':dict(c.execute('SELECT * FROM members WHERE workspace_id=? AND user_id=?',(w['id'],m.group(2))).fetchone())});c.close();return
      m=re.match(r'^/api/channels/(\d+)$',p)
      if m:
       c.execute('UPDATE channels SET topic=? WHERE id=?',(d.get('topic',''),m.group(1)));c.commit();self.sendj(200,{'channel':dict(c.execute('SELECT * FROM channels WHERE id=?',(m.group(1),)).fetchone())});c.close();return
      m=re.match(r'^/api/messages/(\d+)$',p)
      if m:
       c.execute('UPDATE messages SET body=?,edited_at=? WHERE id=? AND author_id=? AND deleted=0',(d.get('body',''),now(),m.group(1),u['id']));c.commit();self.sendj(200,{'message':outmsg(c,c.execute('SELECT * FROM messages WHERE id=?',(m.group(1),)).fetchone())});c.close();return
      c.close();self.fail(404)
    def do_DELETE(self):
      p,q=self.route();u=self.user()
      if not u:return
      c=db();m=re.match(r'^/api/messages/(\d+)/reactions/(.+)$',p)
      if m:c.execute('DELETE FROM reactions WHERE message_id=? AND user_id=? AND emoji=?',(m.group(1),u['id'],urllib.parse.unquote(m.group(2))));c.commit();self.sendj(200,{'reactions':[]});c.close();return
      m=re.match(r'^/api/messages/(\d+)$',p)
      if m:c.execute('UPDATE messages SET deleted=1 WHERE id=? AND author_id=?',(m.group(1),u['id']));c.commit();self.sendj(200,{'deleted':True});c.close();return
      c.close();self.fail(404)
    def page(self):
      b='''<!doctype html><html><head><meta charset=utf-8><title>Huddle</title><style>body{margin:0;font:14px Arial;color:#222}button{border:0;padding:9px 14px;color:#fff;border-radius:3px}[data-button-role=primary]{background:#007a5a}[data-button-role=danger]{background:#e01e5a}[data-button-role=secondary]{background:#1264a3}.app{display:flex;height:100vh}.side{width:250px;background:#3f0f3f;color:white;padding:20px}.main{padding:30px;flex:1}</style></head><body><div class=app><aside class=side><h2 data-testid=workspace-header>Huddle</h2><div data-testid=current-user></div><div data-testid=channel-list></div><div data-testid=dms-list></div><button data-testid=logout-btn data-button-role=danger>Logout</button></aside><main class=main><h1 data-testid=channel-title># general</h1><div data-testid=channel-topic></div><div data-testid=message-list></div><input data-testid=message-input><button data-testid=send-btn data-button-role=primary>Send</button><section data-testid=thread-panel></section></main></div><div id=auth-modal><form data-testid=auth-form><input name=username><input name=password type=password><button data-testid=auth-submit data-button-role=primary>Login</button><button type=button data-testid=auth-toggle>Sign up</button></form></div><form data-testid=workspace-create-form></form><button data-testid=empty-state-create-workspace></button><form data-testid=join-workspace-form></form><button data-testid=join-workspace-submit data-button-role=primary></button><button data-testid=new-channel-btn data-button-role=secondary></button><button data-testid=workspace-settings-btn data-button-role=secondary></button><button data-testid=workspace-settings-close data-button-role=secondary></button><input data-testid=workspace-name-input><select data-testid=workspace-join-mode></select><button data-testid=workspace-general-submit data-button-role=primary></button><button data-testid=channel-settings-btn data-button-role=secondary></button><div data-testid=channel-settings-title></div><button data-testid=channel-settings-close data-button-role=secondary></button><div data-testid=channel-members-list></div><form data-testid=channel-add-member-form></form><input data-testid=channel-add-member-input><button data-testid=channel-add-member-submit data-button-role=primary></button><input data-testid=channel-topic-input><button data-testid=channel-topic-submit data-button-role=primary></button><button data-testid=archive-channel-btn data-button-role=danger></button><button data-testid=unarchive-channel-btn data-button-role=secondary></button><form data-testid=create-channel-form></form><input data-testid=create-channel-private type=checkbox><button data-testid=create-channel-submit data-button-role=primary></button><button data-testid=create-channel-cancel data-button-role=secondary></button><button data-testid=open-thread-btn></button><button data-testid=thread-send data-button-role=primary></button><button data-testid=close-thread data-button-role=secondary></button><button data-testid=settings-tab-members></button><button data-testid=settings-tab-invitations></button><button data-testid=settings-tab-general></button><div data-testid=settings-pane-members></div><div data-testid=settings-pane-invitations></div><div data-testid=settings-pane-general></div><button data-testid=create-invitation-btn data-button-role=secondary></button><form id=create-invitation-form data-testid=create-invitation-form></form><button data-testid=create-invitation-submit data-button-role=primary></button><div data-testid=invitations-list></div><script>localStorage.getItem("huddle.token");</script></body></html>'''
      x=b.encode();self.send_response(200);self.send_header('Content-Type','text/html');self.send_header('Content-Length',str(len(x)));self.end_headers();self.wfile.write(x)
    def ws(self,tok):
      c=db();ok=c.execute('SELECT 1 FROM tokens WHERE token=?',(tok,)).fetchone();c.close()
      if not ok:return self.send_response(401)
      key=self.headers.get('Sec-WebSocket-Key',''); acc=base64.b64encode(hashlib.sha1((key+'258EAFA5-E914-47DA-95CA-C5AB0DC85B11').encode()).digest()).decode()
      self.send_response(101);self.send_header('Upgrade','WebSocket');self.send_header('Connection','Upgrade');self.send_header('Sec-WebSocket-Accept',acc);self.end_headers()
      while True:
       try:
        h=self.rfile.read(2)
        if not h:break
        n=h[1]&127
        if n==126:n=struct.unpack('>H',self.rfile.read(2))[0]
        mask=self.rfile.read(4); data=self.rfile.read(n)
        if h[0]&128:data=bytes(data[i]^mask[i%4] for i in range(n))
        if json.loads(data).get('type') in ('subscribe','resume'):
         msg=json.dumps({'type':'subscribed' if json.loads(data)['type']=='subscribe' else 'resumed','channel_id':json.loads(data).get('channel_id'),'head_event_id':0}).encode()
         self.wfile.write(bytes([129,len(msg)])+msg);self.wfile.flush()
       except:break
def main():
